function poly(coef, x){ var v=0; for(var i=0;i<coef.length;i++){ v=v*x+coef[i]; } return v; }
function bisection(coef, lo, hi, tol){ var flo=poly(coef,lo), fhi=poly(coef,hi);
  if(flo*fhi>0) return NaN;
  for(var i=0;i<200;i++){ var mid=(lo+hi)/2; var fm=poly(coef,mid);
    if(Math.abs(fm)<tol || (hi-lo)/2<tol) return mid;
    if(flo*fm<0){ hi=mid; fhi=fm; } else { lo=mid; flo=fm; } }
  return (lo+hi)/2; }
var EXPORTS={poly:poly,bisection:bisection};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
